import { useEffect, useState, type FormEvent } from "react";
import { useSearchParams } from "react-router-dom";
import { buscarLivros, formatarData, type Livro } from "../api.ts";

/** A resposta da API, junto com o termo que a produziu. */
type Resultado = {
  termo: string;
  livros: Livro[];
  erro: string;
};

export default function BuscarLivros() {
  // o termo mora na URL (/?q=...): recarregar a página repete a busca
  const [params, setParams] = useSearchParams();
  const termo = params.get("q") ?? "";

  const [resultado, setResultado] = useState<Resultado | null>(null);

  useEffect(() => {
    if (termo === "") return;

    // se o termo mudar antes da resposta chegar, a resposta antiga é ignorada
    let ignorar = false;

    buscarLivros(termo)
      .then((livros) => {
        if (!ignorar) setResultado({ termo, livros, erro: "" });
      })
      .catch((e: Error) => {
        if (!ignorar) setResultado({ termo, livros: [], erro: e.message });
      });

    return () => {
      ignorar = true;
    };
  }, [termo]);

  // ainda não chegou resposta para o termo que está na URL
  const carregando = resultado?.termo !== termo;

  function buscar(evento: FormEvent<HTMLFormElement>) {
    evento.preventDefault();

    const q = String(new FormData(evento.currentTarget).get("q")).trim();

    setParams(q === "" ? {} : { q });
  }

  return (
    <section>
      {/* React 19: <title> dentro do componente vai parar no <head> */}
      <title>Buscar livros · Biblioteca</title>

      <h1>Buscar livros</h1>

      <form className="busca" onSubmit={buscar}>
        <input
          // key: quando a URL muda (menu, voltar), o campo recomeça com o termo dela
          key={termo}
          name="q"
          defaultValue={termo}
          placeholder="ISBN, título ou nome do autor"
          aria-label="Termo de busca"
        />
        <button type="submit">Buscar</button>
      </form>

      {termo === "" ? (
        <p className="dica">Digite um ISBN, parte do título ou o nome do autor.</p>
      ) : carregando ? (
        <p className="dica">Buscando…</p>
      ) : resultado.erro !== "" ? (
        <p className="erro">{resultado.erro}</p>
      ) : resultado.livros.length === 0 ? (
        <p className="dica">Nenhum livro encontrado para “{termo}”.</p>
      ) : (
        <div
          className="resultado-busca"
          role="region"
          aria-label="Livros encontrados"
          tabIndex={0}
        >
          <table>
            <thead>
              <tr>
                <th>ISBN</th>
                <th>Título</th>
                <th>Autor</th>
                <th>Catalogado em</th>
              </tr>
            </thead>
            <tbody>
              {resultado.livros.map((livro) => (
                <tr key={livro.id}>
                  <td>{livro.isbn}</td>
                  <td>{livro.titulo}</td>
                  <td>{livro.autor}</td>
                  <td>{formatarData(livro.dataCatalogacao)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </section>
  );
}

import { useState, type FormEvent } from "react";
import { Link } from "react-router-dom";
import { cadastrarLivro, formatarData, type Livro } from "../api.ts";

export default function CadastrarLivro() {
  const [salvo, setSalvo] = useState<Livro | null>(null);
  const [erro, setErro] = useState("");
  const [enviando, setEnviando] = useState(false);

  async function cadastrar(evento: FormEvent<HTMLFormElement>) {
    evento.preventDefault();

    const formulario = evento.currentTarget;
    const dados = new FormData(formulario);

    setEnviando(true);
    setErro("");
    setSalvo(null);

    try {
      const livro = await cadastrarLivro({
        isbn: String(dados.get("isbn")),
        titulo: String(dados.get("titulo")),
        autorId: Number(dados.get("autorId")),
      });

      setSalvo(livro);
      formulario.reset();
    } catch (e) {
      // as regras continuam no backend: aqui só mostramos o que ele respondeu
      setErro((e as Error).message);
    } finally {
      setEnviando(false);
    }
  }

  return (
    <section>
      <title>Cadastrar livro · Biblioteca</title>

      <h1>Cadastrar livro</h1>

      <form className="cadastro" onSubmit={cadastrar}>
        <label>
          ISBN
          <input name="isbn" required placeholder="9780321125217" />
        </label>

        <label>
          Título
          <input name="titulo" required />
        </label>

        <label>
          Autor (id)
          <input name="autorId" type="number" min="1" required />
          <small>
            Carga inicial: 1 Eric Evans · 2 Robert C. Martin · 3 Harper Lee · 4 Jane
            Austen
          </small>
        </label>

        <button type="submit" disabled={enviando}>
          {enviando ? "Cadastrando…" : "Cadastrar"}
        </button>
      </form>

      {erro !== "" && <p className="erro">{erro}</p>}

      {salvo !== null && (
        <div className="sucesso">
          <p>
            <strong>{salvo.titulo}</strong> entrou no catálogo em {formatarData(salvo.dataCatalogacao)}.
          </p>
          <Link to={`/?q=${salvo.isbn}`}>Ver no acervo</Link>
        </div>
      )}
    </section>
  );
}

import type { Clock } from "../../../shared/Clock";

export type Reserva = {
  id: number; leitorId: number; exemplarId: number; dataReserva: string;
  dataLimiteRetirada: string; dataExpiracao: string;
  situacao: "ativa" | "cancelada" | "atendida";
};
export type Emprestimo = {
  id: number; leitorId: number; exemplarId: number; dataEmprestimo: string;
  dataPrevistaDevolucao: string; dataDevolucao: string | null;
};
export type DadosLeitor = { id: number; nome: string; cpf: string };
export type DadosExemplar = { id: number; livroTitulo: string; numeroRegistro: string };
export type Filtros = { leitorId?: number; exemplarId?: number; situacao?: string };

/** Somente as portas permitem consultar leitores e acervo. */
export interface ConsultaDeCirculacao {
  leitor(id: number): Promise<DadosLeitor | null>;
  exemplar(id: number): Promise<DadosExemplar | null>;
}

export interface RepositorioCirculacao {
  reservas(filtros?: Filtros): Promise<Reserva[]>;
  emprestimos(filtros?: Filtros): Promise<Emprestimo[]>;
  inserirReserva(dados: Omit<Reserva, "id">): Promise<Reserva>;
  situacaoReserva(id: number, situacao: "cancelada" | "atendida"): Promise<void>;
  inserirEmprestimo(dados: Omit<Emprestimo, "id">): Promise<Emprestimo>;
  devolverEmprestimo(id: number, data: string): Promise<void>;
}

/** Datas civis da biblioteca: o início/fim da janela não depende do fuso do navegador. */
export function hoje(clock: Clock = () => new Date()): string {
  return clock().toLocaleDateString("en-CA", { timeZone: "America/Sao_Paulo" });
}

export function somarDias(data: string, quantidade: number): string {
  const dia = new Date(`${data}T12:00:00Z`);
  dia.setUTCDate(dia.getUTCDate() + quantidade);
  return dia.toISOString().slice(0, 10);
}

export function situacaoReserva(reserva: Reserva, data: string): Reserva["situacao"] | "expirada" {
  return reserva.situacao === "ativa" && data >= reserva.dataExpiracao ? "expirada" : reserva.situacao;
}

export function situacaoEmprestimo(emprestimo: Emprestimo, data: string): "em_aberto" | "atrasado" | "devolvido" {
  if (emprestimo.dataDevolucao) return "devolvido";
  return data > emprestimo.dataPrevistaDevolucao ? "atrasado" : "em_aberto";
}

export function diasDeAtraso(emprestimo: Emprestimo, data: string): number {
  const fim = emprestimo.dataDevolucao ?? data;
  return Math.max(0, Math.round((Date.parse(fim) - Date.parse(emprestimo.dataPrevistaDevolucao)) / 86_400_000));
}

import type { Clock } from "../../../shared/Clock";
import { NotFound } from "../../../shared/errors";
import {
  diasDeAtraso, hoje, situacaoEmprestimo, situacaoReserva,
  type ConsultaDeCirculacao, type Emprestimo, type RepositorioCirculacao, type Reserva,
} from "./modelo";

/** Cada comando é executado pelo adaptador HTTP dentro da transação compartilhada. */
export class BaseCirculacao {
  constructor(
    protected readonly repositorio: RepositorioCirculacao,
    protected readonly consulta: ConsultaDeCirculacao,
    protected readonly clock: Clock = () => new Date(),
  ) {}

  protected async verificarVinculos(leitorId: number, exemplarId: number): Promise<void> {
    if (!await this.consulta.leitor(leitorId)) throw new NotFound("Leitor não encontrado.");
    if (!await this.consulta.exemplar(exemplarId)) throw new NotFound("Exemplar não encontrado.");
  }

  protected async detalhes(leitorId: number, exemplarId: number) {
    const [leitor, exemplar] = await Promise.all([this.consulta.leitor(leitorId), this.consulta.exemplar(exemplarId)]);
    return { leitorNome: leitor?.nome ?? "", leitorCpf: leitor?.cpf ?? "",
      livroTitulo: exemplar?.livroTitulo ?? "", numeroRegistro: exemplar?.numeroRegistro ?? "" };
  }

  protected async apresentarReserva(reserva: Reserva) {
    return { ...reserva, situacao: situacaoReserva(reserva, hoje(this.clock)),
      ...await this.detalhes(reserva.leitorId, reserva.exemplarId) };
  }

  protected async apresentarEmprestimo(emprestimo: Emprestimo) {
    const data = hoje(this.clock);
    return { ...emprestimo, situacao: situacaoEmprestimo(emprestimo, data),
      diasDeAtraso: diasDeAtraso(emprestimo, data),
      ...await this.detalhes(emprestimo.leitorId, emprestimo.exemplarId) };
  }
}

import { RuleConflict } from "../../../shared/errors";
import { hoje, situacaoReserva, somarDias } from "./modelo";
import { BaseCirculacao } from "./BaseCirculacao";

export class ReservarExemplar extends BaseCirculacao {
  async executar(leitorId: number, exemplarId: number) {
    await this.verificarVinculos(leitorId, exemplarId);
    const data = hoje(this.clock);
    const reservasLeitor = await this.repositorio.reservas({ leitorId });
    if (reservasLeitor.filter(r => situacaoReserva(r, data) === "ativa").length >= 2) {
      throw new RuleConflict("O leitor já possui duas reservas ativas.");
    }
    const reservasExemplar = await this.repositorio.reservas({ exemplarId });
    const emprestimosExemplar = await this.repositorio.emprestimos({ exemplarId });
    if (reservasExemplar.some(r => situacaoReserva(r, data) === "ativa") || emprestimosExemplar.some(e => !e.dataDevolucao)) {
      throw new RuleConflict("Exemplar indisponível para reserva.");
    }
    const reserva = await this.repositorio.inserirReserva({ leitorId, exemplarId, dataReserva: data,
      dataLimiteRetirada: somarDias(data, 6), dataExpiracao: somarDias(data, 7), situacao: "ativa" });
    return this.apresentarReserva(reserva);
  }

}

import type { SQL } from "bun";

/** Sem FKs entre módulos: os vínculos são validados pelas portas na mesma transação. */
export async function prepararCirculacao(db: SQL): Promise<void> {
  await db`CREATE TABLE IF NOT EXISTS reservas (
    id SERIAL PRIMARY KEY,
    leitor_id INTEGER NOT NULL,
    exemplar_id INTEGER NOT NULL,
    data_reserva TEXT NOT NULL,
    data_limite_retirada TEXT NOT NULL,
    data_expiracao TEXT NOT NULL,
    situacao TEXT NOT NULL CHECK (situacao IN ('ativa', 'cancelada', 'atendida'))
  )`;
  await db`CREATE INDEX IF NOT EXISTS reservas_leitor ON reservas (leitor_id)`;
  await db`CREATE INDEX IF NOT EXISTS reservas_exemplar ON reservas (exemplar_id)`;
  await db`CREATE TABLE IF NOT EXISTS emprestimos (
    id SERIAL PRIMARY KEY,
    leitor_id INTEGER NOT NULL,
    exemplar_id INTEGER NOT NULL,
    data_emprestimo TEXT NOT NULL,
    data_prevista_devolucao TEXT NOT NULL,
    data_devolucao TEXT
  )`;
  await db`CREATE UNIQUE INDEX IF NOT EXISTS emprestimo_aberto_exemplar ON emprestimos (exemplar_id)
    WHERE data_devolucao IS NULL`;
  await db`CREATE INDEX IF NOT EXISTS emprestimos_leitor ON emprestimos (leitor_id)`;
}

import type { SQL } from "bun";
import type { Emprestimo, Filtros, RepositorioCirculacao, Reserva } from "../domain/modelo";

export class CirculacaoPostgres implements RepositorioCirculacao {
  constructor(private readonly db: SQL) {}

  async reservas(filtros: Filtros = {}): Promise<Reserva[]> {
    return await this.db<Reserva[]>`SELECT id, leitor_id AS "leitorId", exemplar_id AS "exemplarId",
      data_reserva AS "dataReserva", data_limite_retirada AS "dataLimiteRetirada",
      data_expiracao AS "dataExpiracao", situacao FROM reservas
      WHERE (${filtros.leitorId ?? null}::INTEGER IS NULL OR leitor_id = ${filtros.leitorId ?? null})
        AND (${filtros.exemplarId ?? null}::INTEGER IS NULL OR exemplar_id = ${filtros.exemplarId ?? null})
      ORDER BY id DESC`;
  }

  async emprestimos(filtros: Filtros = {}): Promise<Emprestimo[]> {
    return await this.db<Emprestimo[]>`SELECT id, leitor_id AS "leitorId", exemplar_id AS "exemplarId",
      data_emprestimo AS "dataEmprestimo", data_prevista_devolucao AS "dataPrevistaDevolucao",
      data_devolucao AS "dataDevolucao" FROM emprestimos
      WHERE (${filtros.leitorId ?? null}::INTEGER IS NULL OR leitor_id = ${filtros.leitorId ?? null})
        AND (${filtros.exemplarId ?? null}::INTEGER IS NULL OR exemplar_id = ${filtros.exemplarId ?? null})
      ORDER BY id DESC`;
  }

  async inserirReserva(dados: Omit<Reserva, "id">): Promise<Reserva> {
    const [row] = await this.db`INSERT INTO reservas
      (leitor_id, exemplar_id, data_reserva, data_limite_retirada, data_expiracao, situacao)
      VALUES (${dados.leitorId}, ${dados.exemplarId}, ${dados.dataReserva}, ${dados.dataLimiteRetirada}, ${dados.dataExpiracao}, ${dados.situacao})
      RETURNING id`;
    return { ...dados, id: Number(row!.id) };
  }

  async situacaoReserva(id: number, situacao: "cancelada" | "atendida"): Promise<void> {
    await this.db`UPDATE reservas SET situacao = ${situacao} WHERE id = ${id}`;
  }

  async inserirEmprestimo(dados: Omit<Emprestimo, "id">): Promise<Emprestimo> {
    const [row] = await this.db`INSERT INTO emprestimos
      (leitor_id, exemplar_id, data_emprestimo, data_prevista_devolucao, data_devolucao)
      VALUES (${dados.leitorId}, ${dados.exemplarId}, ${dados.dataEmprestimo}, ${dados.dataPrevistaDevolucao}, ${dados.dataDevolucao})
      RETURNING id`;
    return { ...dados, id: Number(row!.id) };
  }

  async devolverEmprestimo(id: number, data: string): Promise<void> {
    await this.db`UPDATE emprestimos SET data_devolucao = ${data} WHERE id = ${id}`;
  }
}

