import type { ConsultaDeCirculacao, Emprestimo, Filtros, RepositorioCirculacao, Reserva } from "../src/modules/circulacao/domain/modelo";
import type { BaseCirculacao } from "../src/modules/circulacao/domain/BaseCirculacao";
